let asset = AVURLAsset(url: URL(fileURLWithPath: src))
let gen = AVAssetImageGenerator(asset: asset)
gen.appliesPreferredTrackTransform = true
gen.requestedTimeToleranceBefore = .zero
gen.requestedTimeToleranceAfter = .zero
// no maximumSize -> full resolution

// args: time, x, y, w, h, scale, label   (in FULL-RES pixel coords, origin top-left)
func crop(_ t: Double, _ x: Int, _ y: Int, _ w: Int, _ h: Int, _ scale: Int, _ label: String) {
    let cmt = CMTime(seconds: t, preferredTimescale: 600)
    guard let cg = try? gen.copyCGImage(at: cmt, actualTime: nil) else { print("fail \(t)"); return }
    let rect = CGRect(x: x, y: y, width: w, height: h)
    guard let sub = cg.cropping(to: rect) else { print("cropfail"); return }
    let outW = w*scale, outH = h*scale
    let ctx = CGContext(data: nil, width: outW, height: outH, bitsPerComponent: 8, bytesPerRow: 0,
                        space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!
    ctx.interpolationQuality = .high
    ctx.draw(sub, in: CGRect(x: 0, y: 0, width: outW, height: outH))
    let scaled = ctx.makeImage()!
    let rep = NSBitmapImageRep(cgImage: scaled)
    let data = rep.representation(using: .png, properties: [:])!
    let path = "\(outDir)/crop_\(label).png"
    try! data.write(to: URL(fileURLWithPath: path))
    print("wrote \(path)  (src full \(cg.width)x\(cg.height))")
}

// Video controls (bottom-right of hero video). Full res 1438x1020.
